#define MAXN 100
#define MAXM 1000
#define MAXQ 100
#define INF 1000000000

int n, m, q;
int dist[MAXN][MAXN];
int dp[1 << MAXQ][MAXQ];
int requests[MAXQ][2]; // [0] = house, [1] = deadline

int min(int a, int b) {
    return a < b ? a : b;
}

int solve() {
    // Floyd-Warshall for all-pairs shortest paths
    for (int k = 0; k < n; k++) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (dist[i][k] < INF && dist[k][j] < INF) {
                    dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j]);
                }
            }
        }
    }

    // Check if any request is impossible to reach from start (house 0)
    for (int i = 0; i < q; i++) {
        if (dist[0][requests[i][0]] >= INF) {
            return -1;
        }
    }

    // DP over subsets
    int total = 1 << q;
    for (int mask = 0; mask < total; mask++) {
        for (int i = 0; i < q; i++) {
            dp[mask][i] = INF;
        }
    }

    // Initialize with starting from house 0
    for (int i = 0; i < q; i++) {
        dp[1 << i][i] = dist[0][requests[i][0]];
    }

    // Fill DP table
    for (int mask = 1; mask < total; mask++) {
        for (int last = 0; last < q; last++) {
            if (!(mask & (1 << last))) continue;
            if (dp[mask][last] == INF) continue;

            for (int next = 0; next < q; next++) {
                if (mask & (1 << next)) continue;
                int new_mask = mask | (1 << next);
                int new_time = dp[mask][last] + dist[requests[last][0]][requests[next][0]];
                if (new_time <= requests[next][1]) {
                    dp[new_mask][next] = min(dp[new_mask][next], new_time);
                }
            }
        }
    }

    // Find minimum Santas using DP results
    // We'll do a greedy/DP approach: find maximum subset that one Santa can do
    int full_mask = total - 1;
    int santas = 0;
    int covered = 0;

    // DP to find max requests one Santa can handle
    int max_one[1 << MAXQ];
    for (int mask = 0; mask < total; mask++) {
        max_one[mask] = 0;
        for (int last = 0; last < q; last++) {
            if (dp[mask][last] < INF) {
                int cnt = __builtin_popcount(mask);
                if (cnt > max_one[mask]) max_one[mask] = cnt;
            }
        }
    }

    // Greedy: repeatedly take the largest feasible subset
    while (covered != full_mask) {
        int best_mask = 0;
        int best_cnt = 0;
        int remaining = full_mask ^ covered;

        // Try all subsets of remaining
        for (int sub = remaining; sub; sub = (sub - 1) & remaining) {
            if (max_one[sub] > best_cnt) {
                best_cnt = max_one[sub];
                best_mask = sub;
            }
        }

        if (best_cnt == 0) return -1; // impossible
        covered |= best_mask;
        santas++;
    }

    return santas;
}

