#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

#define INF 1000000000

typedef struct {
    int to, w, next;
} Edge;

typedef struct {
    int t, house;
} Req;

static int cmp_req(const void *a, const void *b) {
    const Req *x = (const Req *)a;
    const Req *y = (const Req *)b;
    if (x->t != y->t) return x->t - y->t;
    return x->house - y->house;
}

int main(void) {
    int n, m, k;

    while (scanf("%d %d %d", &n, &m, &k) == 3) {
        if (n == 0 && m == 0 && k == 0) break;

        int maxEdges = 2 * m + 5;
        Edge *edges = (Edge *)malloc(sizeof(Edge) * maxEdges);
        int *head = (int *)malloc(sizeof(int) * (n + 1));
        int edgeCnt = 0;

        for (int i = 1; i <= n; i++) head[i] = -1;

        for (int i = 0; i < m; i++) {
            int a, b, c;
            scanf("%d %d %d", &a, &b, &c);

            edges[edgeCnt].to = b;
            edges[edgeCnt].w = c;
            edges[edgeCnt].next = head[a];
            head[a] = edgeCnt++;

            edges[edgeCnt].to = a;
            edges[edgeCnt].w = c;
            edges[edgeCnt].next = head[b];
            head[b] = edgeCnt++;
        }

        Req *req = (Req *)malloc(sizeof(Req) * k);
        for (int i = 0; i < k; i++) {
            scanf("%d %d", &req[i].house, &req[i].t);
        }

        qsort(req, k, sizeof(Req), cmp_req);

        /* Floyd/All-pairs would be too heavy in C for larger n.
           We only need distances from house 1 and request houses.
           So run Dijkstra from each relevant source. */

        int *sources = (int *)malloc(sizeof(int) * (k + 1));
        sources[0] = 1;
        for (int i = 0; i < k; i++) sources[i + 1] = req[i].house;

        int S = k + 1;
        int *distMat = (int *)malloc(sizeof(int) * S * (n + 1));

        /* Simple O(S * n^2 + S * m) Dijkstra using arrays */
        int *dist = (int *)malloc(sizeof(int) * (n + 1));
        int *used = (int *)malloc(sizeof(int) * (n + 1));

        for (int s = 0; s < S; s++) {
            for (int i = 1; i <= n; i++) {
                dist[i] = INF;
                used[i] = 0;
            }
            dist[sources[s]] = 0;

            for (int it = 1; it <= n; it++) {
                int v = -1;
                for (int i = 1; i <= n; i++) {
                    if (!used[i] && (v == -1 || dist[i] < dist[v])) v = i;
                }
                if (v == -1 || dist[v] == INF) break;
                used[v] = 1;
                for (int e = head[v]; e != -1; e = edges[e].next) {
                    int to = edges[e].to;
                    int nd = dist[v] + edges[e].w;
                    if (nd < dist[to]) dist[to] = nd;
                }
            }

            for (int i = 1; i <= n; i++) {
                distMat[s * (n + 1) + i] = dist[i];
            }
        }

        /* Build DAG of feasible consecutive deliveries:
           i -> j if same Santa can do request i then request j.
           Also Santa starts at house 1 at time 0, so request i is startable if dist(1, house_i) <= t_i.
           Minimum path cover in DAG = k - maximum matching. */

        int *startable = (int *)calloc(k, sizeof(int));
        for (int i = 0; i < k; i++) {
            int d0 = distMat[0 * (n + 1) + req[i].house];
            if (d0 <= req[i].t) startable[i] = 1;
        }

        int *adj = (int *)malloc(sizeof(int) * k * k);
        int *deg = (int *)calloc(k, sizeof(int));

        for (int i = 0; i < k; i++) {
            int *di = &distMat[(i + 1) * (n + 1)];
            for (int j = i + 1; j < k; j++) {
                int travel = di[req[j].house];
                if (travel < INF && req[i].t + travel <= req[j].t) {
                    adj[i * k + deg[i]++] = j;
                }
            }
        }

        /* Keep only requests that are reachable from start.
           Unreachable requests can never be served, but problem guarantees feasibility in standard versions.
           For robustness, if any request is not startable and has no predecessor chain from a startable one,
           matching formulation below still yields a count, but impossible cases are not specified.
        */

        int *matchR = (int *)malloc(sizeof(int) * k);
        for (int i = 0; i < k; i++) matchR[i] = -1;

        int *vis = (int *)malloc(sizeof(int) * k);

        int aug_dfs(int u) {
            for (int idx = 0; idx < deg[u]; idx++) {
                int v = adj[u * k + idx];
                if (vis[v]) continue;
                vis[v] = 1;
                if (matchR[v] == -1 || aug_dfs(matchR[v])) {
                    matchR[v] = u;
                    return 1;
                }
            }
            return 0;
        }

        int matching = 0;
        for (int i = 0; i < k; i++) {
            memset(vis, 0, sizeof(int) * k);
            if (aug_dfs(i)) matching++;
        }

        int answer = k - matching;
        printf("%d\n", answer);

        free(edges);
        free(head);
        free(req);
        free(sources);
        free(distMat);
        free(dist);
        free(used);
        free(startable);
        free(adj);
        free(deg);
        free(matchR);
        free(vis);
    }

    return 0;
}

