    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        while (true) {
            String line = br.readLine();
            if (line == null) break;
            String[] parts = line.split(" ");
            int n = Integer.parseInt(parts[0]);
            int m = Integer.parseInt(parts[1]);
            int q = Integer.parseInt(parts[2]);
            if (n == 0 && m == 0 && q == 0) break;

            int[][] dist = new int[n][n];
            for (int i = 0; i < n; i++) {
                Arrays.fill(dist[i], INF);
                dist[i][i] = 0;
            }

            for (int i = 0; i < m; i++) {
                parts = br.readLine().split(" ");
                int u = Integer.parseInt(parts[0]) - 1;
                int v = Integer.parseInt(parts[1]) - 1;
                int t = Integer.parseInt(parts[2]);
                dist[u][v] = Math.min(dist[u][v], t);
                dist[v][u] = Math.min(dist[v][u], t);
            }

            // Floyd-Warshall
            for (int k = 0; k < n; k++) {
                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < n; j++) {
                        if (dist[i][k] < INF && dist[k][j] < INF) {
                            dist[i][j] = Math.min(dist[i][j], dist[i][k] + dist[k][j]);
                        }
                    }
                }
            }

            int[] s = new int[q];
            int[] d = new int[q];
            int[] time = new int[q];
            for (int i = 0; i < q; i++) {
                parts = br.readLine().split(" ");
                s[i] = Integer.parseInt(parts[0]) - 1;
                d[i] = Integer.parseInt(parts[1]) - 1;
                time[i] = Integer.parseInt(parts[2]);
            }

            // Build bipartite matching graph
            List<Integer>[] graph = new ArrayList[q];
            for (int i = 0; i < q; i++) graph[i] = new ArrayList<>();

            for (int i = 0; i < q; i++) {
                for (int j = 0; j < q; j++) {
                    if (i == j) continue;
                    // Can Santa do i then j?
                    if (dist[d[i]][s[j]] < INF &&
                        time[i] + dist[d[i]][s[j]] <= time[j]) {
                        graph[i].add(j);
                    }
                }
            }

            int matchR[] = new int[q];
            Arrays.fill(matchR, -1);
            int result = 0;
            for (int u = 0; u < q; u++) {
                boolean seen[] = new boolean[q];
                if (bpm(u, graph, seen, matchR)) result++;
            }

            System.out.println(q - result);
        }
    }

    static boolean bpm(int u, List<Integer>[] graph, boolean[] seen, int[] matchR) {
        for (int v : graph[u]) {
            if (!seen[v]) {
                seen[v] = true;
                if (matchR[v] == -1 || bpm(matchR[v], graph, seen, matchR)) {
                    matchR[v] = u;
                    return true;
                }
            }
        }
        return false;
    }
}

