    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextInt()) {
            int N = sc.nextInt(); // houses
            if (N == 0) break;
            int M = sc.nextInt(); // roads
            int R = sc.nextInt(); // requests

            int[][] dist = new int[N][N];
            for (int[] row : dist) Arrays.fill(row, INF);
            for (int i = 0; i < N; i++) dist[i][i] = 0;

            for (int i = 0; i < M; i++) {
                int u = sc.nextInt() - 1;
                int v = sc.nextInt() - 1;
                int w = sc.nextInt();
                dist[u][v] = Math.min(dist[u][v], w);
                dist[v][u] = Math.min(dist[v][u], w);
            }

            // Floyd-Warshall
            for (int k = 0; k < N; k++)
                for (int i = 0; i < N; i++)
                    for (int j = 0; j < N; j++)
                        if (dist[i][k] < INF && dist[k][j] < INF)
                            dist[i][j] = Math.min(dist[i][j], dist[i][k] + dist[k][j]);

            int[] house = new int[R];
            int[] deadline = new int[R];
            for (int i = 0; i < R; i++) {
                house[i] = sc.nextInt() - 1;
                deadline[i] = sc.nextInt();
            }

            // Build bipartite graph: edge i->j if Santa can do i then j
            List<List<Integer>> adj = new ArrayList<>();
            for (int i = 0; i < R; i++) adj.add(new ArrayList<>());

            for (int i = 0; i < R; i++) {
                for (int j = 0; j < R; j++) {
                    if (i != j && deadline[i] + dist[house[i]][house[j]] <= deadline[j]) {
                        adj.get(i).add(j);
                    }
                }
            }

            // Maximum bipartite matching
            int[] match = new int[R];
            Arrays.fill(match, -1);
            int matched = 0;
            for (int i = 0; i < R; i++) {
                boolean[] visited = new boolean[R];
                if (dfs(i, adj, match, visited)) matched++;
            }

            System.out.println(R - matched);
        }
    }

    static boolean dfs(int u, List<List<Integer>> adj, int[] match, boolean[] visited) {
        for (int v : adj.get(u)) {
            if (!visited[v]) {
                visited[v] = true;
                if (match[v] == -1 || dfs(match[v], adj, match, visited)) {
                    match[v] = u;
                    return true;
                }
            }
        }
        return false;
    }
}

import java.io.*;
import java.util.*;

/*
 * ICPC - Minimum number of Santas
 *
 * We are given multiple datasets.
 * Each dataset:
 *   n m b
 *   m roads: u v t   (undirected, travel time t)
 *   b requests: house deadline
 *
 * A Santa can deliver multiple requests if he can visit them in some order and
 * reach each requested house no later than its deadline. All Santas start from
 * house 1 at time 0.
 *
 * We must find the minimum number of Santas needed to satisfy all requests.
 *
 * Standard reduction:
 * 1) Compute shortest paths between relevant nodes using Floyd-Warshall.
 * 2) Sort requests by deadline.
 * 3) Build a DAG where edge i -> j exists if one Santa can do request i and then j:
 *      dist(1, house_i) <= deadline_i
 *      and max(dist(1, house_i), deadline_i?) Actually the Santa may wait, so after
 *      delivering i at any time <= deadline_i, earliest completion of i is dist(1, house_i),
 *      and to maximize feasibility we use earliest possible arrival.
 *      Thus i -> j iff
 *          dist(1, house_i) <= deadline_i
 *          dist(1, house_i) + dist(house_i, house_j) <= deadline_j
 *    Also a request alone is feasible iff dist(1, house_i) <= deadline_i.
 *
 * Since requests are sorted by deadline, this DAG is acyclic.
 *
 * Minimum path cover in DAG = b - maximum matching in corresponding bipartite graph.
 * That equals minimum number of Santas.
 *
 * Input format is inferred from the statement fragment. Commonly datasets end with 0 0 0.
 */

public class Main {
    static final long INF = (long) 4e18;

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return Long.MIN_VALUE;
            } while (c <= ' ');

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class HopcroftKarp {
        int nLeft, nRight;
        List<Integer>[] g;
        int[] dist, matchL, matchR;

        @SuppressWarnings("unchecked")
        HopcroftKarp(int nLeft, int nRight) {
            this.nLeft = nLeft;
            this.nRight = nRight;
            g = new ArrayList[nLeft];
            for (int i = 0; i < nLeft; i++) g[i] = new ArrayList<>();
            matchL = new int[nLeft];
            matchR = new int[nRight];
            Arrays.fill(matchL, -1);
            Arrays.fill(matchR, -1);
            dist = new int[nLeft];
        }

        void addEdge(int u, int v) {
            g[u].add(v);
        }

        boolean bfs() {
            ArrayDeque<Integer> q = new ArrayDeque<>();
            boolean found = false;
            for (int i = 0; i < nLeft; i++) {
                if (matchL[i] == -1) {
                    dist[i] = 0;
                    q.add(i);
                } else {
                    dist[i] = -1;
                }
            }

            while (!q.isEmpty()) {
                int u = q.poll();
                for (int v : g[u]) {
                    int w = matchR[v];
                    if (w != -1 && dist[w] == -1) {
                        dist[w] = dist[u] + 1;
                        q.add(w);
                    }
                    if (w == -1) found = true;
                }
            }
            return found;
        }

        boolean dfs(int u) {
            for (int v : g[u]) {
                int w = matchR[v];
                if (w == -1 || (dist[w] == dist[u] + 1 && dfs(w))) {
                    matchL[u] = v;
                    matchR[v] = u;
                    return true;
                }
            }
            dist[u] = -1;
            return false;
        }

        int maxMatching() {
            int res = 0;
            while (bfs()) {
                for (int i = 0; i < nLeft; i++) {
                    if (matchL[i] == -1 && dfs(i)) res++;
                }
            }
            return res;
        }
    }

    static class Request {
        int house;
        long deadline;
        Request(int house, long deadline) {
            this.house = house;
            this.deadline = deadline;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder out = new StringBuilder();

        while (true) {
            long a = fs.nextLong();
            if (a == Long.MIN_VALUE) break;
            int n = (int) a;
            int m = fs.nextInt();
            int b = fs.nextInt();

            if (n == 0 && m == 0 && b == 0) break;

            long[][] dist = new long[n][n];
            for (int i = 0; i < n; i++) {
                Arrays.fill(dist[i], INF);
                dist[i][i] = 0;
            }

            for (int i = 0; i < m; i++) {
                int u = fs.nextInt() - 1;
                int v = fs.nextInt() - 1;
                long t = fs.nextLong();
                if (t < dist[u][v]) {
                    dist[u][v] = t;
                    dist[v][u] = t;
                }
            }

            Request[] req = new Request[b];
            for (int i = 0; i < b; i++) {
                int house = fs.nextInt() - 1;
                long deadline = fs.nextLong();
                req[i] = new Request(house, deadline);
            }

            // All-pairs shortest paths
            for (int k = 0; k < n; k++) {
                for (int i = 0; i < n; i++) {
                    if (dist[i][k] == INF) continue;
                    for (int j = 0; j < n; j++) {
                        if (dist[k][j] == INF) continue;
                        long nd = dist[i][k] + dist[k][j];
                        if (nd < dist[i][j]) dist[i][j] = nd;
                    }
                }
            }

            Arrays.sort(req, Comparator.comparingLong(r -> r.deadline));

            boolean[] feasible = new boolean[b];
            int feasibleCount = 0;
            for (int i = 0; i < b; i++) {
                if (dist[0][req[i].house] <= req[i].deadline) {
                    feasible[i] = true;
                    feasibleCount++;
                }
            }

            // If some request is individually impossible, then under usual problem statements
            // input should guarantee feasibility. We still handle it defensively.
            if (feasibleCount < b) {
                out.append("impossible\n");
                continue;
            }

            HopcroftKarp hk = new HopcroftKarp(b, b);

            for (int i = 0; i < b; i++) {
                for (int j = i + 1; j < b; j++) {
                    long d1 = dist[0][req[i].house];
                    long between = dist[req[i].house][req[j].house];
                    if (d1 < INF && between < INF && d1 + between <= req[j].deadline) {
                        hk.addEdge(i, j);
                    }
                }
            }

            int matching = hk.maxMatching();
            int answer = b - matching;
            out.append(answer).append('\n');
        }

        System.out.print(out.toString());
    }
}

