        # Read roads
        for _ in range(m):
            u = int(next(it))
            v = int(next(it))
            d = int(next(it))
            if d < dist[u][v]:
                dist[u][v] = d
                dist[v][u] = d

        # Floyd-Warshall for all-pairs shortest paths
        for k in range(n):
            for i in range(n):
                for j in range(n):
                    if dist[i][k] < INF and dist[k][j] < INF:
                        if dist[i][k] + dist[k][j] < dist[i][j]:
                            dist[i][j] = dist[i][k] + dist[k][j]

        # Read requests
        requests = []
        for _ in range(q):
            h = int(next(it))
            t = int(next(it))
            requests.append((h, t))

        # If no requests, 0 Santas needed
        if q == 0:
            results.append("0")
            continue

        # Check feasibility: if any request is unreachable from itself (impossible case)
        feasible = True
        for h, t in requests:
            if dist[h][h] != 0:
                feasible = False
                break
        if not feasible:
            results.append(str(q))  # worst case: each request needs one Santa
            continue

        # DP over subsets: dp[mask][last] = minimum time to complete deliveries in mask ending at last
        dp = [[INF] * q for _ in range(1 << q)]
        for i in range(q):
            h, t = requests[i]
            if dist[0][h] <= t:
                dp[1 << i][i] = dist[0][h]

        for mask in range(1 << q):
            for last in range(q):
                if dp[mask][last] == INF:
                    continue
                cur_time = dp[mask][last]
                cur_house = requests[last][0]
                for nxt in range(q):
                    if mask & (1 << nxt):
                        continue
                    nxt_house, nxt_deadline = requests[nxt]
                    travel = dist[cur_house][nxt_house]
                    if travel == INF:
                        continue
                    arrival = cur_time + travel
                    if arrival <= nxt_deadline:
                        new_mask = mask | (1 << nxt)
                        if arrival < dp[new_mask][nxt]:
                            dp[new_mask][nxt] = arrival

        # Minimum number of Santas: find smallest k such that we can cover all requests
        # Use BFS over subset coverings
        full_mask = (1 << q) - 1
        # Precompute which subsets are feasible by a single Santa
        feasible_subsets = []
        for mask in range(1 << q):
            if any(dp[mask][i] < INF for i in range(q)):
                feasible_subsets.append(mask)

        # DP for minimum Santas: min_santas[mask]
        min_santas = [INF] * (1 << q)
        min_santas[0] = 0
        for mask in range(1 << q):
            if min_santas[mask] == INF:
                continue
            for sub in feasible_subsets:
                if mask & sub == 0:
                    new_mask = mask | sub
                    if min_santas[mask] + 1 < min_santas[new_mask]:
                        min_santas[new_mask] = min_santas[mask] + 1

        results.append(str(min_santas[full_mask]))

    sys.stdout.write("\n".join(results))

