            b = int(next(it))
        except StopIteration:
            break

        if n == 0 and m == 0 and b == 0:
            break

        adj = [[] for _ in range(n)]
        for _ in range(m):
            u = int(next(it)) - 1
            v = int(next(it)) - 1
            w = int(next(it))
            adj[u].append((v, w))
            adj[v].append((u, w))

        requests = []
        houses = []
        times = []
        for _ in range(b):
            h = int(next(it)) - 1
            t = int(next(it))
            houses.append(h)
            times.append(t)
            requests.append((t, h))

        # Sort requests by deadline/time
        order = sorted(range(b), key=lambda i: times[i])
        sorted_times = [times[i] for i in order]
        sorted_houses = [houses[i] for i in order]

        # Distances needed: from depot(0) and from each distinct requested house
        needed_sources = {0}
        for h in sorted_houses:
            needed_sources.add(h)

        dist_map = {}
        for s in needed_sources:
            dist_map[s] = dijkstra(s, adj, n)

        # Build DAG: i -> j if one Santa can do request i then j
        # Need: time_i + travel(i_house, j_house) <= time_j
        g = [[] for _ in range(b)]
        feasible_start = [False] * b
        for i in range(b):
            if dist_map[0][sorted_houses[i]] <= sorted_times[i]:
                feasible_start[i] = True

        # If a request is unreachable from depot by its time, impossible in usual sense.
        # Problem statements of this kind typically guarantee feasibility;
        # if not, minimum number of Santas is still b if each impossible alone doesn't help.
        # We proceed with path cover on feasible chaining.
        for i in range(b):
            hi = sorted_houses[i]
            ti = sorted_times[i]
            dhi = dist_map[hi]
            for j in range(i + 1, b):
                if ti + dhi[sorted_houses[j]] <= sorted_times[j]:
                    g[i].append(j)

        # Minimum path cover in DAG = b - maximum matching
        matching = hopcroft_karp(g, b, b)
        ans = b - matching
        out.append(str(ans))

    sys.stdout.write("\n".join(out))

