#include <bits/stdc++.h>
using namespace std;

/*
This problem is the classic "minimum path cover in a DAG" after computing
reachability between delivery requests.

Interpretation:
- Santa starts at house 1 at time 0.
- A request (h, t) means a present must be delivered at house h no later than time t.
  Since waiting is allowed, we can treat it as delivered exactly at time t.
- One Santa can do request i before request j iff:
    dist(1, house_i) <= time_i
    and
    if i before j:
        time_i + dist(house_i, house_j) <= time_j
- We build a DAG on feasible requests, and the minimum number of Santas needed
  equals:
      (# feasible requests) - (maximum matching in bipartite graph induced by DAG)

Input format is not explicitly shown in the prompt, but the standard version of
this problem uses multiple datasets:
    n m q
    m lines: u v w
    q lines: house time
repeated until EOF.

Roads are undirected.
*/

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, q;
    while (cin >> n >> m >> q) {
        const long long INF = (1LL << 60);

        vector<vector<long long>> dist(n + 1, vector<long long>(n + 1, INF));
        for (int i = 1; i <= n; ++i) dist[i][i] = 0;

        for (int i = 0; i < m; ++i) {
            int u, v;
            long long w;
            cin >> u >> v >> w;
            dist[u][v] = min(dist[u][v], w);
            dist[v][u] = min(dist[v][u], w);
        }

        // Floyd-Warshall
        for (int k = 1; k <= n; ++k) {
            for (int i = 1; i <= n; ++i) {
                if (dist[i][k] == INF) continue;
                for (int j = 1; j <= n; ++j) {
                    if (dist[k][j] == INF) continue;
                    long long nd = dist[i][k] + dist[k][j];
                    if (nd < dist[i][j]) dist[i][j] = nd;
                }
            }
        }

        vector<pair<int, long long>> req(q);
        for (int i = 0; i < q; ++i) {
            cin >> req[i].first >> req[i].second;
        }

        // Keep only individually feasible requests
        vector<int> house;
        vector<long long> tim;
        for (int i = 0; i < q; ++i) {
            int h = req[i].first;
            long long t = req[i].second;
            if (dist[1][h] <= t) {
                house.push_back(h);
                tim.push_back(t);
            }
        }

        int k = (int)house.size();
        if (k == 0) {
            cout << 0 << '\n';
            continue;
        }

        vector<int> ord(k);
        iota(ord.begin(), ord.end(), 0);
        sort(ord.begin(), ord.end(), [&](int a, int b) {
            if (tim[a] != tim[b]) return tim[a] < tim[b];
            return house[a] < house[b];
        });

        vector<int> H(k);
        vector<long long> T(k);
        for (int i = 0; i < k; ++i) {
            H[i] = house[ord[i]];
            T[i] = tim[ord[i]];
        }

        // Build bipartite graph: i(left) -> j(right) if same Santa can do i then j
        vector<vector<int>> g(k);
        for (int i = 0; i < k; ++i) {
            for (int j = i + 1; j < k; ++j) {
                if (dist[H[i]][H[j]] < INF && T[i] + dist[H[i]][H[j]] <= T[j]) {
                    g[i].push_back(j);
                }
            }
        }

        // Kuhn maximum bipartite matching
        vector<int> mt(k, -1);

        function<bool(int, vector<int>&)> dfs = [&](int v, vector<int>& vis) -> bool {
            if (vis[v]) return false;
            vis[v] = 1;
            for (int to : g[v]) {
                if (mt[to] == -1 || dfs(mt[to], vis)) {
                    mt[to] = v;
                    return true;
                }
            }
            return false;
        };

        int matching = 0;
        for (int v = 0; v < k; ++v) {
            vector<int> vis(k, 0);
            if (dfs(v, vis)) ++matching;
        }

        cout << (k - matching) << '\n';
    }

    return 0;
}
